  'INDUSTRIAL_ZONE': (24,14),
  'AQUEDUCT': (23,14),
  'DAM': (23,15),
  'NEIGHBORHOOD_1': (24,13),
  'NEIGHBORHOOD_2': (24,15),
  'NEIGHBORHOOD_3': (23,13),
