def is_mountain(tt):
    return 'MOUNTAIN' in tt

def has_river(x,y):
    ne,wf,nw=rivers.get(pid(x,y),(0,0,0))
    return bool(ne or wf or nw)

def feature_at(x,y):
    return features.get(pid(x,y))

def terrain_at(x,y):
    return plots[pid(x,y)][0]

def is_flat_land(x,y):
    tt=terrain_at(x,y)
    if is_water(tt) or is_mountain(tt):
        return False
    return True

# validate city center
cc_tt=terrain_at(*CITY_CENTER)
assert is_flat_land(*CITY_CENTER)

# no overlaps
coords=list(placements.values())
assert len(coords)==len(set(coords))

