    tt=terrain_at(x,y)
    ft=feature_at(x,y)
    if k in ('HARBOR','WATER_PARK'):
        if not is_water(tt):
            raise SystemExit(f'{k} not on water')
    else:
        if is_water(tt) or is_mountain(tt):
            raise SystemExit(f'{k} invalid terrain {tt}')
    if ft=='FEATURE_GEOTHERMAL_FISSURE':
        raise SystemExit(f'{k} on fissure')

