x,y=placements['DAM']
if feature_at(x,y)!='FEATURE_FLOODPLAINS_PLAINS':
    raise SystemExit('dam not on floodplains')
ne,wf,nw=rivers.get(pid(x,y),(0,0,0))
if int(ne)+int(wf)+int(nw) < 2:
    raise SystemExit('dam river edges <2')

# aqueduct rule
x,y=placements['AQUEDUCT']
if hex_distance(CITY_CENTER,(x,y))!=1:
    raise SystemExit('aqueduct not adjacent to city center')
# fresh water: river on aqueduct tile OR adjacent mountain
fresh = has_river(x,y) or any(in_bounds(nx,ny) and is_mountain(terrain_at(nx,ny)) for nx,ny in neighbors(x,y))
if not fresh:
    raise SystemExit('aqueduct lacks fresh water')

