cx,cy=placements['CAMPUS']
base=0
# mountains +1
mount=sum(1 for nx,ny in neighbors(cx,cy) if in_bounds(nx,ny) and is_mountain(terrain_at(nx,ny)))
base += mount
# fissure/reef +2 each
for nx,ny in neighbors(cx,cy):
    if not in_bounds(nx,ny):
        continue
    ft=feature_at(nx,ny)
    if ft=='FEATURE_GEOTHERMAL_FISSURE':
        base += 2
    if ft=='FEATURE_REEF':
        base += 2
# rainforest +0.5 each
rf=sum(1 for nx,ny in neighbors(cx,cy) if in_bounds(nx,ny) and feature_at(nx,ny)=='FEATURE_JUNGLE')
base += (rf//2)
# district minor
dcount=district_adj_count((cx,cy))
base += (dcount//2)
adj['CAMPUS']=base

