hx,hy=placements['COMMERCIAL_HUB']
ch=0
ch += 2 if has_river(hx,hy) else 0
# adjacent harbor +2 each (none)
# district minor
ch += (district_adj_count((hx,hy))//2)
adj['COMMERCIAL_HUB']=ch

# industrial zone
ix,iy=placements['INDUSTRIAL_ZONE']
iz=0
# +2 each adjacent aqueduct/dam/canal
for nx,ny in neighbors(ix,iy):
    if (nx,ny)==placements['AQUEDUCT']:
        iz += 2
    if (nx,ny)==placements['DAM']:
        iz += 2
# mines/lumber etc none
iz += (district_adj_count((ix,iy))//2)
adj['INDUSTRIAL_ZONE']=iz

# others 0
for k in placements:
    if k in ('CAMPUS','COMMERCIAL_HUB','INDUSTRIAL_ZONE'):
        continue
    # normalize neighborhoods to 'NEIGHBORHOOD'
    if k.startswith('NEIGHBORHOOD'):
        continue
    adj[k]=0

print('Adjacencies:', adj)
print('district_adj_counts:', {
    'CAMPUS': district_adj_count(placements['CAMPUS']),
    'COMMERCIAL_HUB': district_adj_count(placements['COMMERCIAL_HUB']),
    'INDUSTRIAL_ZONE': district_adj_count(placements['INDUSTRIAL_ZONE']),
})
print('total:', sum(adj.values()))
print('dist to center:', {k:hex_distance(CITY_CENTER,v) for k,v in placements.items()})
